ate There are risks to travellers in river areas towards the west of Amazonas State, where Brazil shares borders with Colombia, Peru and Venezuela, due to criminal activity."}],"url":"https://www.gov.uk/foreign-travel-advice/brazil","read":"2026-08-19","page_updated":"2026-05-11T12:32:48+01:00"}},"timing":{"peak":["Mar-Apr","Aug-Sep"],"peak_note":"Best flow + weather; Apr-May the single best window","summer_note":"Dec-Feb hot/rainiest/highest-water but most crowded","dry_note":"Jun-Aug cooler/calmer but lower flow","inflection":["~February (into Mar-Apr peak)","~July (into Aug-Sep peak)"],"fire_date":"curve-start minus 1-2 weeks — mid-to-late January (Mar-Apr travel) and late June (Aug-Sep travel)","off_season_fill":"Dec-Feb: sell max-roar high-water spectacle + Belmond honeymoon; bundle Itaipu-by-night + Parque das Aves"},"jewels":[{"si_tag":"expedition","name":"Trilha das Cataratas panoramic walkway + Devil''s Throat balcony","tier":"essential","source":"https://iguazufalls-tickets.org/what-to-see/iguazu-falls-brazil-side-viewpoints/ (Accessed 2026-07-07)","timing":"[''Mar-Apr'', ''Aug-Sep'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The defining Brazilian-side experience: 1.4-km rim walk to the wide-angle Devil''s Throat view and panoramic elevator","si":"expedition","blurb":"The defining Brazilian-side experience: 1.4-km rim walk to the wide-angle Devil''s Throat view and panoramic elevator","when":"[''Mar-Apr'', ''Aug-Sep'']","commission":"park entry non-commissionable; guided-trail + transfer margin via DMC/OTA","accessed":"2026-07-07"},{"si_tag":"expedition","name":"Macuco Safari — boat under the falls","tier":"comfort","source":"https://www.viator.com/tours/Foz-do-Iguacu/Macuco-Safari-Boat-Ride/d970-7558P14 (Accessed 2026-07-07)","timing":"[''Mar-Apr'', ''Aug-Sep'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The three-stage jungle-trail-boat run that soaks you beneath the cataracts","si":"expedition","blurb":"The three-stage jungle-trail-boat run that soaks you beneath the cataracts","when":"[''Mar-Apr'', ''Aug-Sep'']","commission":"OTA affiliate on operator margin; park-entry portion non-commissionable; from ~US$109/adult","accessed":"2026-07-07"},{"si_tag":"expedition","name":"Helicopter over the falls (Helisul)","tier":"premier","source":"https://www.viator.com/tours/Foz-do-Iguacu/Panoramic-Helicopter-Flight-Iguazu-Falls-by-Helisul-Aviation/d970-216404P1 (Accessed 2026-07-07)","timing":"[''Mar-Apr'', ''Aug-Sep'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"10–12 min, both sides + Devil''s Throat in one frame, 7-seat cap","si":"expedition","blurb":"10–12 min, both sides + Devil''s Throat in one frame, 7-seat cap","when":"[''Mar-Apr'', ''Aug-Sep'']","commission":"OTA affiliate; US$120-166/pp; 7-seat cap","accessed":"2026-07-07"},{"si_tag":"expedition","name":"Sunrise-before-crowds at the falls (in-park hotel)","tier":"luxury","source":"https://www.foratravel.com/trip-reports/A84HTP/a-stay-at-brazils-only-hotel-within-iguazu-falls-belmond-das-cataratas-saima-khan (Accessed 2026-07-07)","timing":"[''Mar-Apr'', ''Aug-Sep'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Only Belmond das Cataratas guests walk the trails before the 9am public opening — the falls, alone, at first light","si":"expedition","blurb":"Only Belmond das Cataratas guests walk the trails before the 9am public opening — the falls, alone, at first light","when":"[''Mar-Apr'', ''Aug-Sep'']","commission":"Belmond via Virtuoso/Fora consortium","accessed":"2026-07-07"},{"si_tag":"romance","name":"Belmond das Cataratas terrace at sunset","tier":"luxury","source":"https://www.belmond.com/hotels/south-america/brazil/iguassu-falls/belmond-hotel-das-cataratas/location (Accessed 2026-07-07)","timing":"[''Mar-Apr'', ''Aug-Sep'']","when_source":"derived from destination timing","timing_