  ('iguazu-falls-argentina', '10S', 'Iguazú Falls (Argentine Side)', 'Argentina', 'Iguazú Falls (Argentine Side)', 'live', 'verified', 'mountainValley', 'Northwest, Mendoza Wine & Iguazú', '{"expedition","culture"}', '{}', '{"essential","comfort","luxury","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","emergency_secondary":["101 police","107 ambulance (SAME)","100 fire","0800 999 5000 tourist line"],"advisory_level":"L1","book_enabled":true,"bin":"freely bookable (L1)","consent_flow":false,"air_access_verified":true,"air_access_note":"Puerto Iguazu / Cataratas del Iguazu Intl (IGR) via Buenos Aires AEP (domestic) / EZE (international); daily nonstops on Aerolineas Argentinas / Flybondi / JetSmart; IGR<->AEP among busiest domestic routes","trauma_note":"Puerto Iguazu hospital stabilises; serious trauma evac to Buenos Aires by air (IGR->AEP/EZE)","falls_footing":"catwalks + circuit boardwalks/stairs permanently misted & slippery; Lower Circuit most stair-heavy; Throat catwalk can close on river surge","gran_aventura_boat":"mandatory life jacket + briefing + dry-bags; jacket-quality reviews mixed; total soaking; river-level-dependent","triple_frontier_note":"Argentina-Brazil-Paraguay convergence is a transnational-crime region; avoid the Paraguay/Ciudad del Este side casually; park + Puerto Iguazu core safe with standard precautions; cross to Brazil before nightfall","health":"Misiones = CDC yellow-fever recommended + dengue risk; DEET, dawn/dusk cover, pre-travel vaccination consult","wildlife":"coatis bold near viewpoints — do NOT feed (bite/scratch)","mandatory_insurance":"Non-resident travel medical insurance required since 2025-07-01 (hospitalisation, repatriation, evacuation)","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/argentina","read":"2026-08-19","page_updated":"2026-05-07T17:26:11+01:00"}},"timing":{"peak_experience":"Mar-Apr & Aug-Sep (best flow-weather-crowd balance)","peak_flow_and_crowds":"Dec-Feb (max water flow, heat >35C, peak crowds); Easter week (Apr) crowd spike","shoulder_sleeper":"May (autumn flow, 30-40% lower rates)","quietest_days":"Tue-Thu","full_moon_walk":"5 nights/month only — plan around lunar calendar; 3 nightly departures, ~2.5 hr","fire_date":"curve-start minus 1-2 weeks; ~2 weeks before visible curve for a standard trip, but 6-12 months ahead for Awasi Iguazu or an in-park Gran Melia falls-view room"},"jewels":[{"name":"Garganta del Diablo catwalk (Devil''s Throat)","si_tag":"expedition","tier":"essential","source":"https://iguazufalls-tickets.org/what-to-see/devils-throat-iguazu-falls/","hook":"the marquee: 1.1 km of steel walkway out over the U-shaped canyon where 14 falls drop 82 m into permanent mist","si":"expedition","blurb":"the marquee: 1.1 km of steel walkway out over the U-shaped canyon where 14 falls drop 82 m into permanent mist","commission":"park-fee entry (non-commissionable) + DMC land package / activity affiliate framing"},{"name":"Upper Circuit","si_tag":"expedition","tier":"essential","source":"https://iguazufalls.com/travel-guide/the-circuits-in-iguazu-falls/","hook":"~1.75 km, mostly flat, top-down panoramas across the cataract chain; the accessible headline alongside the Throat catwalk","si":"expedition","blurb":"~1.75 km, mostly flat, top-down panoramas across the cataract chain; the accessible headline alongside the Throat catwalk","commission":"park-fee + DMC/affiliate"},{"name":"Lower Circuit + Isla San Martín boat","si_tag":"expedition","tier":"essential","source":"https://iguazutickets.com/guides/what-to-see-at-iguazu-falls/","hook":"~1.7 km, stairs down to the base, closest in-your-face angle, plus the passenger boat to the rocky Isla San Martín and its beach","si":"expedition","blurb":"~1.7 km, stairs down to the base, closest in-your-face angle, plus the passenger boat to the rocky Isla San Martín and its beach","commission":"park-fee + DMC/affiliate"},{"name":"Gran Aventura — under-the-falls boat + 4x4","si_tag":"expedition","tier":"comfort","source":"https://iguazufalls.com/tours-and-activities/gran-aventura-activity/","hook":"the adrenaline jewel: 4×4 jungle trail to Puerto Macuco, then a 6 km semi-rigid run into the San Martín falls \"baptism of the mists.\"","si":"expedition","blurb":"the adrenaline jewel: 4×4 jungle trail to Puerto Macuco, then a 6 km semi-rigid run into the San Martín falls \"baptism of the mists.\"","commission":"in-park concession (largely non-commissionable) — package via DMC / frame via activity affiliate"},{"name":"Full-Moon Walk (Paseos de Luna Llena)","si_tag":"expedition","tier":"comfort","source":"https://iguazufalls.com/tours-and-activities/full-moon-walk-tour/","hook":"5 nights a month only, timed to the full moon: welcome drink + Guaraní music, Eco-Train through the night jungle to the Throat catwalk","si":"expedition","blurb":"5 nights a month only, timed to the full moon: welcome drink + Guaraní music, Eco-Train through the night jungle to the Throat catwalk","commission":"guided-only ticket via activity affiliate + DMC"},{"name":"Sunrise with in-park hotel (Gran Meliá privilege)","si_tag":"GEA/RHN","tier":"ultra","source":"https://www.jacadatravel.com/latin-america/argentina/iguazu-falls/accommodation/melia-iguazu/","si":"GEA/RHN","commission":"in-park hotel booking (ultra lane)"},{"name":"Macuco jungle trail","si_tag":"expedition","tier":"essential","source":"http://www.iguazujungle.com/eng/web2/","hook":"the park''s longer forest walk to a hidden waterfall; coatis, toucans, capuchins, butterflies","si":"expedition","blurb":"the park''s longer forest walk to a hidden waterfall; coatis, toucans, capuchins, butterflies","commission":"self-guided or guided via in-park operator + DMC"},{"name":"Güirá Oga wildlife refuge","si_tag":"expedition","tier":"essential","source":"https://www.welcomeargentina.com/puertoiguazu/lodge-awasi-iguazu_i.html","hook":"\"bird house\" in Guaraní; a rescue-and-rehab centre for trafficked/injured native fauna just outside Puerto Iguazú","si":"expedition","blurb":"\"bird house\" in Guaraní; a rescue-and-rehab centre for trafficked/injured native fauna just outside Puerto Iguazú","commission":"activity affiliate + DMC add-on"},{"name":"Brazilian-side panorama day-trip","si_tag":"culture","tier":"comfort","source":"https://sayhueque.com/our-trips/iguazu-falls/","hook":"cross to Parque Nacional do Iguaçu for the whole-system framed view Argentina can''t give you; passport-required border crossing, ~3–4 hr","si":"culture","blurb":"cross to Parque Nacional do Iguaçu for the whole-system framed view Argentina can''t give you; passport-required border crossing, ~3–4 hr","commission":"DMC/guided transfer + activity affiliate (cross-ref Brazil-side dossier)"},{"name":"San Ignacio Miní (UNESCO Jesuit-Guaraní mission)","si_tag":"culture","tier":"essential","source":"https://whc.unesco.org/en/list/275/","hook":"the roofless red-sandstone cathedral of a 1610 Jesuit reduction, UNESCO-listed 1984, ~300 km south toward Posadas","si":"culture","blurb":"the roofless red-sandstone cathedral of a 1610 Jesuit reduction, UNESCO-listed 1984, ~300 km south toward Posadas","commission":"DMC / guided excursion + activity affiliate"}],"faq":[{"q":"What''s the best plan for a day at Iguazú Falls?","a":"Run the Devil''s Throat first at the 08:00 park opening, then work back through the Upper and Lower Circuits. The park opens 08:00 and closes 18:00 with last falls access around 16:30, and starting at the Garganta station gives the best rainbow light and thinnest crowds; budget 5–6 hours minimum for all three circuits plus the Eco-Train.","source":"iguazufalls-tickets.org, Accessed 2026-07-07","si_tag":"expedition"},{"q":"When is the best time to visit Iguazú Falls?","a":"March–April and August–September are the sweet spot, because they balance strong water flow with comfortable 20–30 °C temperatures and manageable crowds. December–February brings maximum flow but heat above 35 °C and peak crowds, while May is a quiet sleeper month with autumn flow and room rates 30–40% below the Dec–Feb peak.","source":"iguazutickets.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"Where should honeymooners stay at Iguazú?","a":"The two scarce in-jewel beds are the play: Awasi Iguazú (Relais & Châteaux, 14 stilted villas with a private guide and 4×4 each) and the Gran Meliá Iguazú, the only hotel inside the Argentine park. Both are near-zero on bedbanks and contract direct or via DMC, so book Awasi or an in-park falls-view room 6–12 months ahead.","source":"relaischateaux.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"Should I visit the Brazilian side too — and what else is nearby?","a":"Yes if time allows: Argentina holds ~80% of the falls and the immersion, while Brazil''s single panoramic boardwalk delivers the whole-system view as a passport-required border day-trip. South toward Posadas, the roofless red-sandstone cathedral of San Ignacio Miní (UNESCO-listed 1984) rounds out a cultural-heritage circuit.","source":"sayhueque.com, Accessed 2026-07-07","si_tag":"culture"},{"q":"What''s the real risk to plan for at Iguazú?","a":"Health and weather, not crime. Misiones province carries a CDC yellow-fever vaccination recommendation and a real dengue risk, so pack DEET and get a pre-travel vaccination consult; the catwalks are permanently misted and slippery, and extreme rainfall can close the Devil''s Throat catwalk on river surge.","source":"wwwnc.cdc.gov, Accessed 2026-07-07","si_tag":"safety"},{"q":"Is the Gran Aventura speedboat dangerous?","a":"It is operator-run and low-risk with the rules followed, but not trivial. A life jacket is mandatory and a safety briefing is given before the 6 km run into the San Martín falls; jacket-quality reviews are mixed, so non-swimmers should weigh the run, everyone gets thoroughly soaked, and the trip is river-level-dependent and cancels in high water.","source":"iguazufalls.com, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Iguazú Falls, Argentine Side: Devil''s Throat, the Circuits & Gran Aventura Boat | TravelWell.World","meta_description":"Stand over the Devil''s Throat, walk the Upper and Lower Circuits, run the Gran Aventura boat under the falls, and stay inside the national park — the complete guide to the Argentine side of Iguazú.","long_tail_en":["iguazu falls argentine side guide","garganta del diablo devil''s throat iguazu","iguazu upper and lower circuits","gran aventura boat ride iguazu","iguazu falls full moon walk","best time to visit iguazu falls","gran melia iguazu in-park hotel","awasi iguazu relais chateaux","iguazu argentina vs brazil side","san ignacio mini jesuit ruins"],"search_language":"es-AR","local_keywords":["Cataratas del Iguazú","Garganta del Diablo","Gran Aventura Iguazú","circuito superior e inferior Iguazú","Tren Ecológico de la Selva","paseo de luna llena Cataratas","San Ignacio Miní ruinas","qué hacer en Puerto Iguazú"],"hreflang":["en","es-AR"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","primary_keyword":"Iguazú Falls (Argentine Side)"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"culture","status":"live"}],"ultra":[{"name":"Awasi Iguazu","type":"Relais & Chateaux all-inclusive villa lodge","location":"Misiones jungle, ~20 min from falls","earning":"Virtuoso/Fora advisor commission + amenities","mor":"AOR/advisor","tier":"ultra"},{"name":"Gran Melia Iguazu","type":"in-park hotel (only one, Argentine side)","location":"inside Iguazu National Park","earning":"advisor/DMC commission + RedLevel upsell","mor":"AOR/advisor/DMC","tier":"ultra"},{"name":"Loi Suites Iguazu","type":"upscale jungle-river resort","location":"Iryapu reserve, ~10 min from Puerto Iguazu","earning":"advisor/DMC commission","mor":"AOR/DMC","tier":"luxury"}],"source_verified":null,"hero":{"query":"Iguazú Falls (Argentine Side), Argentina"},"geo":{"lat":-25.6953,"lng":-54.4367}}'::jsonb, 63),
  ('isla-contoy-mexico', '10S', 'Isla Contoy', 'Mexico', '*If it''s 200 people a day on an island', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"expedition","ocean","wildlife"}', '{}', '{"comfort"}', 'comfort', null, '{"key_facts":["Uninhabited national park capped at 200 visitors/day, authorized tours only","UNESCO-recognized reserve, habitat for 173+ bird species (frigatebirds, pelicans)","Ixlaché reef marks the northern start of the world''s 2nd-largest barrier reef","Sea-turtle nesting May-October; ~30 km north of Isla Mujeres","Day-trip only (no lodging); ~7-8 hr tours from Cancún/Isla Mujeres marinas"],"safety":{"emergency":"911","hospital":"uninhabited - no on-island care; evac via Isla Mujeres to Cancún (Galenia/Hospiten - verify)","advisory_level":"L2","malaria":"none in QR tourist zones (verify); dengue precautions","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Dec-Apr (dry, calm seas, best Ixlaché clarity) + Jun-Sep whale-shark corridor (sold as whale-shark + Contoy combos = true event peak)","shoulder":"May-Jun & Nov (easier permit-day availability; May-Jun straddles whale-shark open + turtle-nesting start)","green":"Jun-mid-Oct (hurricane season; exposed ~30 km open-water crossing - trips cancel in rough seas; disclose cancellation policy)","booking_lead":"200/day cap + authorized-only = book 3-6+ wks in peak (combos sell out with summer 30-39-day window), 1-3 wks shoulder; popular operators + calm-sea Sundays fill first","off_season_specials":"no beds - ''fill-the-permit-days'': green/shoulder = calm-day nature escape (birds + Ixlaché) bundled with off-island Isla Mujeres/Cancún stay","event_peaks":"Christmas-NY + spring break (Dec-Apr); sea-turtle nesting (May-Oct) + whale-shark run (Jun-Sep) are the island''s wildlife event peaks","campaign_start":"whale-shark + Contoy combo Mar-Apr (6-8 wks pre-open); dry-season Ixlaché day-trip Aug-Sep; always pair with off-island stay CTA"},"jewels":[{"name":"Contoy authorized eco-expedition (200/day cap)","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","hook":"permitted boat + guided trail through frigatebird/pelican colonies","bookable_category":"authorized eco day tour","source":"https://contoyadventures.com/isla-contoy/","timing":"Dec-Apr  + Jun-Sep whale-shark corridor","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"permitted boat + guided trail through frigatebird/pelican colonies","when":"Dec-Apr  + Jun-Sep whale-shark corridor","commission":"authorized operator → DMC/curated (park fee pass-through)"},{"name":"Ixlaché reef snorkel","si_tag":"Ocean Adventures","status":"future","tier":"comfort","hook":"northern start of world''s 2nd-largest barrier reef, 17 hard + 14 soft corals","bookable_category":"snorkel stop within Contoy tour","source":"https://contoyadventures.com/isla-contoy/","timing":"Dec-Apr  + Jun-Sep whale-shark corridor","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"northern start of world''s 2nd-largest barrier reef, 17 hard + 14 soft corals","when":"Dec-Apr  + Jun-Sep whale-shark corridor","commission":"authorized operator → curated (bundled)"},{"name":"173+ bird species + sea-turtle nesting","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"frigatebirds, pelicans, green/loggerhead nesting beaches (May-Oct)","bookable_category":"guided nature walk (within tour)","source":"https://nationalparksassociation.org/mexico-national-parks/isla-contoy-national-park/","si":"wildlife","blurb":"frigatebirds, pelicans, green/loggerhead nesting beaches (May-Oct)","commission":"authorized operator → curated (conservation fee non-commissionable)"}],"faq":[{"q":"What''s the real risk to plan for on an Isla Contoy trip?","a":"The open-water crossing and weather — not crime. Contoy sits ~30 km out at the seam where the Caribbean meets the Gulf, an exposed run where sea state can build and operators cancel trips in rough weather (especially hurricane season, Jun–Nov). Pick a calm-sea day, confirm the cancellation/reschedule policy, and keep life jackets on during transit.","source":"airial.travel, 2026-07-04","si_tag":"safety"},{"q":"Is the reef snorkel and boat crossing dangerous?","a":"Both are low-risk with a guide, but respect the water. Snorkeling is snorkel-only with no decompression restriction — the real hazards are the open-water current at the reef seam, boat traffic and sun, so wear the vest, avoid all coral/wildlife contact and stay with the guide. On the ~30 km crossing, follow crew instructions and keep life jackets on.","source":"nationalparksassociation.org, 2026-07-04","si_tag":"safety"},{"q":"How do you actually visit Isla Contoy?","a":"Only through a handful of authorized operators — there is no independent access. The daily cap of 200 visitors makes it scarcity-priced, so book 3–6+ weeks ahead in peak season (1–3 weeks in shoulder); popular operators and calm-sea days fill first. Every trip bundles the park fee, lunch and snorkel gear.","source":"contoyadventures.com / airial.travel, 2026-07-04","si_tag":"expedition"},{"q":"What is the Ixlaché reef snorkel like?","a":"It is the headline in-water stop — the northern start of the world''s second-largest barrier reef. Ixlaché holds 17 hard and 14 soft coral species just south of the island; visibility is clearest in the dry season (Dec–Apr), and the snorkel is included in the guided tour on calm-sea days.","source":"contoyadventures.com, 2026-07-04","si_tag":"ocean"},{"q":"What wildlife will I see on Isla Contoy?","a":"Birds above all — the island is critical habitat for 173+ species, with frigatebird and pelican colonies you pass on the marked trails. Green and loggerhead sea turtles nest on the beaches May–October, adding a seasonal wildlife hook; the whole reserve is car-free and strictly protected.","source":"nationalparksassociation.org, 2026-07-04","si_tag":"wildlife"},{"q":"When is the best time to visit Isla Contoy, and where do trips leave from?","a":"December–April brings the calmest seas and clearest Ixlaché water; the summer whale-shark run (roughly Jun–Sep) is the true event peak, since Contoy is often sold as a whale-shark + Contoy combo. Trips depart Cancún and Isla Mujeres marinas on ~7–8 hour days — there is no lodging, so base off-island.","source":"isla-seatours.com / machupicchu.org, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Isla Contoy, Mexico: 200-a-Day National Park Island","meta_description":"Uninhabited and capped at 200 visitors a day — Isla Contoy''s bird sanctuary and Ixlaché reef are authorized-tour-only. How to book the trip and what to expect.","slug":"isla-contoy-mexico","primary_keyword":"Isla Contoy national park tour","long_tail":["Isla Contoy 200 visitors per day","Ixlaché reef snorkeling","Isla Contoy bird sanctuary","Isla Contoy day trip from Cancún","Isla Contoy authorized operators"],"search_language":"es-MX (restated, not machine-translated)","local_keywords":["tour a Isla Contoy","Parque Nacional Isla Contoy","snorkel arrecife Ixlaché","santuario de aves Isla Contoy","excursión Isla Contoy desde Cancún","operadores autorizados Isla Contoy","combo tiburón ballena e Isla Contoy"],"hreflang":["en","es-MX"],"jsonld_type":"TouristAttraction","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"ocean","status":"future"},{"si":"wildlife","status":"future"}],"ultra":[{"name":"NONE - uninhabited national park, no lodging","why_ultra":"Isla Contoy is an uninhabited national park: no hotels/villas/lodging, no overnight permitted - day-trip add-on, not a stay. Ultra play lives off-island (Isla Mujeres Impression / Cancún Nizuc / Mayakoba corridor - verify municipality)","earning":"n/a on-island; on application via associated Isla Mujeres/Puerto Morelos dossiers","virtuoso_value_add":"n/a on-island - see associated dossiers","mor":"no on-island revenue; commission captured on associated stay + day-tour","source":"https://nationalparksassociation.org/mexico-national-parks/isla-contoy-national-park/"}],"source_verified":"2026-07-04","hero":{"query":"Isla Contoy, Mexico"},"geo":{"lat":21.4833,"lng":-86.7917}}'::jsonb, 64),
  ('izamal-mexico', '10S', 'Izamal', 'Mexico', 'A whole city painted the color of afternoon light', 'live', 'verified', 'kyoto', 'Yucatán (Mérida & Chichén Itzá)', '{"culture","romance","culinary"}', '{}', '{"comfort","premier","ultra"}', null, null, '{"key_facts":["Mexico''s FIRST Pueblo Mágico, designated 2002-02-16 — launched the entire Magical Towns program","Convento de San Antonio de Padua founded 1549 / completed 1561 atop a Maya temple; 75-arch atrium among the largest monastery atriums in the world","Kinich Kakmó pyramid ~200m x ~180m, c. 400-600 AD, dedicated to the Maya sun god, climbable to the summit","Pope John Paul II visited August 1993; standardized ochre-yellow color tradition dates to that visit (''the Yellow City'')","~70 km / ~1h10 from Mérida — an easy day-trip, roughly midway toward Chichén Itzá"],"safety":{"emergency_number":"911","nearest_trauma":"Mérida (~1h10 west; regional hospital hub)","advisory_level":"L1","book_enabled":true,"air_access_verified":true,"air_access_note":"MID Mérida ~1h10 drive; US nonstops incl. Houston, Miami, Dallas, Atlanta","primary_hazards":["heat/sun exposure (shadeless plazas + exposed pyramid climb)","Kinich Kakmó footing (steep, handrail-free Maya steps)","calesa/town traffic (low)","dengue (rainy season)","non-potable tap water"],"climbing_note":"Kinich Kakmó IS climbable to summit — genuine draw; steep uneven risers, no handrails","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"inflection_curve_start":"2026-11-01","peak":"2026-12 to 2027-04","shoulder":"2026-05 to 2026-10 (hot/humid; hurricane exposure Aug-Oct; year-round photo baseline)","fire_date":"2026-10-20","trigger_rule":"curve-start minus 1-2 weeks; front-runs both dry-season inflection and Hanal Pixán; attaches to Mérida-base / in-town boutique lead time","booking_lead_days":{"day_tour":"2-7","in_town_boutique":"7-28","merida_base_high_season":"28-84"},"event_peaks":["Hanal Pixán / Día de Muertos 2026-10-31 to 2026-11-02 (headline)","year-round artisan & photo-travel demand","calesa demand steady all year"],"note":"sharpen on live tracking — Mérida occupancy + Izamal Pueblo-Mágico visitor counts + Hanal Pixán calendar"},"jewels":[{"name":"Convento de San Antonio de Padua (golden convent, sunset)","si_tag":"culture_heritage","source":"https://www.atlasobscura.com/places/yellow-city-of-izamal | Accessed 2026-07-06","si":"culture","commission":"non-commissionable entry; anchors tour + sunset-stay night","accessed":"2026-07-06"},{"name":"Kinich Kakmó pyramid (climbable)","si_tag":"culture_heritage","tier":"comfort","source":"https://tourtochichenitza.com/destinations/izamal | Accessed 2026-07-06","hook":"Unlike El Castillo at Chichén, Izamal''s Kinich Kakmó is climbable to the summit for rooftop views over the yellow city.]","si":"culture","blurb":"Unlike El Castillo at Chichén, Izamal''s Kinich Kakmó is climbable to the summit for rooftop views over the yellow city.]","commission":"day-tour inclusion (guiding); entry non-commissionable","accessed":"2026-07-06"},{"name":"Pope John Paul II heritage (1993 visit, JP-II statue)","si_tag":"culture_heritage","tier":"comfort","source":"https://en.wikipedia.org/wiki/Izamal | Accessed 2026-07-06","si":"culture","commission":"guided-tour narrative anchor; faith-travel draw","accessed":"2026-07-06"},{"name":"Centro Cultural y Artesanal (folk-art museum + workshops)","si_tag":"culture_heritage","tier":"comfort","source":"https://themexicoreport.com/entrepreneurs-preserve-mayan-culture-and-traditions-at-centro-cultural-y-artesanal-in-izamal-yucatan/ | Accessed 2026-07-06","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"experience add-on (affiliate/Viator); workshop packages","accessed":"2026-07-06"},{"name":"Sunset calesa (horse-carriage) ride","si_tag":"romance","tier":"comfort","source":"https://tourtochichenitza.com/destinations/izamal | Accessed 2026-07-06","hook":"low-speed, low-risk, but shared with light town traffic; standard care boarding/alighting. Guided calesa tours are the norm and low-hazard","si":"romance","blurb":"low-speed, low-risk, but shared with light town traffic; standard care boarding/alighting. Guided calesa tours are the norm and low-hazard","commission":"bookable experience add-on (Viator/GetYourGuide; Host for private)","accessed":"2026-07-06"},{"name":"Golden-hour photo circuit (yellow arcades + convent)","si_tag":"romance","tier":"premier","source":"https://www.bontraveler.com/izamal-yucatan-mexico-yellow-city/ | Accessed 2026-07-06","si":"romance","commission":"private photo-tour upsell; drives one-night boutique room-night","accessed":"2026-07-06"},{"name":"Hammock & artisan workshops (huipil, alebrijes)","si_tag":"culinary","tier":"comfort","source":"https://yucatantoday.com/en/blog/yucatans-most-iconic-handcrafts-artisan-towns | Accessed 2026-07-06","si":"culinary","commission":"artisan-experience + retail add-on; Centro Cultural packages","accessed":"2026-07-06"},{"name":"Santa Bárbara cenotes (nearby, ~49 km)","si_tag":"romance","tier":"comfort","source":"https://tourtochichenitza.com/destinations/izamal | Accessed 2026-07-06","si":"romance","commission":"adventure add-on (operator/Viator)","accessed":"2026-07-06"}],"faq":[{"q":"Why is Izamal called the Yellow City, and what makes it special?","a":"It is Mexico''s first Pueblo Mágico (designated 2002), and the entire historic center is painted one standardized ochre-gold — a color tradition set for Pope John Paul II''s August 1993 visit and maintained ever since. The city is built in layers: the Spanish set the great Franciscan convent atop a Maya temple, and the Kinich Kakmó sun-god pyramid still rises above the rooftops.","source":"en.wikipedia.org / casaloltun.com, 2026-07-06","si_tag":"culture"},{"q":"Can you climb the pyramid in Izamal?","a":"Yes — Kinich Kakmó is climbable to the summit, which sets it apart from Chichén Itzá, where El Castillo has been closed to climbers since 2008. The ~200 × 180 m pyramid dates to c. 400–600 AD; the steps are steep, uneven Maya risers with no handrails, so wear sturdy shoes and mind your footing on the descent.","source":"tourtochichenitza.com, 2026-07-06","si_tag":"culture"},{"q":"Is Izamal good for a romantic day or honeymoon?","a":"Yes — it is a golden-hour romance magnet. The convent glows like a lantern above the plaza at sunset, a 45–60 min horse-drawn calesa ride winds through the yellow arcades, and the light seems to come from the buildings themselves. Most couples day-trip it from Mérida (70 km / ~1h10) or book one night in an in-town boutique to shoot the convent at golden hour.","source":"bontraveler.com, 2026-07-06","si_tag":"romance"},{"q":"What is there to do beyond the convent?","a":"Hands-on Maya craft: the Centro Cultural y Artesanal runs artisan workshops and tours to hammock weavers, huipil embroiderers and alebrije painters who often work in-shop while you eat. Yucatecan cuisine and Hanal Pixán (the Maya Day of the Dead food tradition) give a soft culinary layer for later.","source":"yucatantoday.com, 2026-07-06","si_tag":"culinary"},{"q":"What''s the real risk to plan for in Izamal?","a":"Heat and footing, not crime. The shadeless plazas and the exposed, handrail-free Kinich Kakmó climb get hot at midday, so carry water, a hat and sunscreen and shoot golden hour rather than noon. Izamal has local clinics only — the nearest full trauma care is Mérida, ~1h10 west.","source":"travel.state.gov, 2026-07-06","si_tag":"safety"}],"seo":{"jsonld_type":"TouristAttraction","meta_title":"Izamal, the Yellow City: Pueblo Mágico Guide (2026) | TravelWell.World","search_language":"en","local_keywords":["Izamal ciudad amarilla","Convento Izamal","Convento de San Antonio de Padua","pirámide Kinich Kakmó","calesa Izamal","Pueblo Mágico Izamal","artesanías Izamal"],"long_tail_en":["Izamal yellow city guide 2026","Izamal from Mérida day trip","Convento San Antonio de Padua Izamal","Kinich Kakmó pyramid climb","Izamal calesa horse carriage ride","Izamal sunset photography"],"hreflang":["en","es-MX"],"author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06"},"booking":null,"si_checklist_25":null,"sis_present":["culture_heritage","romance","culinary"],"ultra":[{"name":"Hotel San Miguel Arcángel (in-town)","tier":"premier_boutique","earning_path":"Host FIT / MoR","note":"ceiling in-town; no true ultra hotel in Izamal itself","source":"https://yucatantoday.com/en/izamal/ | Accessed 2026-07-06"},{"name":"Chablé Yucatán","tier":"ultra","earning_path":"Virtuoso / Fora","note":"nearest ultra; ~30 min Mérida; #13 World''s Best Hotels 2023","source":"https://www.virtuoso.com/travel/luxury-hotels/15452675/chable-yucatan | Accessed 2026-07-06"},{"name":"Hacienda Temozón (Luxury Collection)","tier":"ultra","earning_path":"Virtuoso / Marriott STARS / Fora / MoR","note":"28-room grand hacienda","source":"https://www.travelweekly.com/Hotels/Abala-Mexico/Hacienda-Temozon-Luxury-Collection-p51093491 | Accessed 2026-07-06"},{"name":"Hacienda Santa Rosa (Luxury Collection)","tier":"ultra","earning_path":"Virtuoso / Marriott STARS / MoR","note":"intimate 11 rooms","source":"https://www.letstraveltomexico.com/yucatan-haciendas/ | Accessed 2026-07-06"}],"source_verified":"2026-07-06","hero":{"query":"Izamal, Mexico"},"geo":{"lat":20.9308,"lng":-89.0175}}'::jsonb, 65),
  ('jericoacoara-brazil', '10S', 'Jericoacoara & the Ceará Coast, Brazil', 'Brazil', 'Jericoacoara & the Ceará Coast', 'live', 'verified', 'tropicalBeach', 'Northeast Beaches & Bahia', '{"tropical","romance"}', '{"tropical"}', '{"essential","comfort","premier"}', null, null, '{"key_facts":null,"safety":{"emergency":"190","advisory_level":"L2","advisory_source":"US State Dept, issued 2025-05-29","book_enabled":true,"bin":"freely bookable (L2)","consent_flow":false,"air_access_verified":true,"air_access":["JJD (Jericoacoara Airport, ~35 min transfer)","FOR (Fortaleza/Pinto Martins) + 4-5 hr authorized 4x4 dune transfer (~300 km)"],"remote_flag":true,"trauma_note":"Remote, road-less; definitive care/evac via Fortaleza then US air evac; factor 4x4-only ground leg; med-evac insurance advised","water_hazards":["riptides/strong currents","shorebreak","strong-wind open-water kite hazard"],"environmental":["high UV / sun exposure","dune heat","minimal shade"],"fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel Amazonas State FCDO advises against all but essential travel to the following river areas towards the west of Amazonas State: along the Amazonas (Amazon) River and its tributaries west of the town of Codajás and east of the town of Belém do Solimões in Amazonas State along any part of the Itaquaí River in Amazonas State along any part of the Japurá River or its tributaries in Amazonas State along the Rio Negro (Black River) and its tributaries north or west of the town of Barcelos in Amazonas State Find out more about why FCDO advises against travel ."},{"form":"against all but essential travel","text":"advises against all but essential travel: along the Amazonas (Amazon) River and its tributaries west of the town of Codajás and east of the town of Belém do Solimões in Amazonas State along any part of the Itaquaí River in Amazonas State along any part of the Japurá River or its tributaries in Amazonas State along the Rio Negro (Black River) and its tributaries north or west of the town of Barcelos in Amazonas State There are risks to travellers in river areas towards the west of Amazonas State, where Brazil shares borders with Colombia, Peru and Venezuela, due to criminal activity."}],"url":"https://www.gov.uk/foreign-travel-advice/brazil","read":"2026-08-19","page_updated":"2026-05-11T12:32:48+01:00"}},"timing":{"peak":"Jul-Dec (kite season; dry; wind nearly daily, 20-25kt building to 30-35kt Sep-Nov, strongest Nov)","spike":"Reveillon ~Dec26-Jan3 (20,000+ visitors, >98% occupancy, AYA + LABRYINTO festivals)","inflection":"late Jun / early Jul (wind curve starts)","green_rainy":"Feb-May (lighter wind ~55-65% good days, fuller lagoons, quiet, value)","fire_date":"mid-to-late June (kite-curve start minus 1-2 weeks)","off_season_fill":"Feb-May romance + lagoon-hammock + value tiers"},"jewels":[{"name":"Sunset Dune (Duna do Pôr do Sol) + capoeira","si_tag":"Tropical/Beaches","tier":"essential","source":"https://www.nextstopbrazil.com/destinations/jericoacoara","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the nightly pilgrimage; sun into the sea, drums on the sand below","si":"Tropical/Beaches","blurb":"the nightly pilgrimage; sun into the sea, drums on the sand below","when":"Jul-Dec","commission":"free ritual → anchor pousada stay + F&B add-on"},{"name":"Lagoa do Paraíso hammocks-in-water","si_tag":"Tropical/Beaches","tier":"essential","source":"https://beachtraveldestinations.com/jericoacoara/","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"wooden hammocks set in a crystal freshwater lagoon; the signature Jeri postcard","si":"Tropical/Beaches","blurb":"wooden hammocks set in a crystal freshwater lagoon; the signature Jeri postcard","when":"Jul-Dec","commission":"buggy day-tour + lagoon-bar F&B"},{"name":"Pedra Furada arch","si_tag":"Tropical/Beaches","tier":"essential","source":"https://www.nextstopbrazil.com/destinations/jericoacoara","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Pedra Furada, a wind-and-sea-carved stone arch, is a ~45-minute coastal walk from the village","si":"Tropical/Beaches","blurb":"Pedra Furada, a wind-and-sea-carved stone arch, is a ~45-minute coastal walk from the village","when":"Jul-Dec","commission":"guided coastal walk / photo tour add-on"},{"name":"Kite at Preá / Guriú","si_tag":"expedition","tier":"essential","source":"https://landedtravel.com/rancho-do-peixe/","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Preá''s flat, steady wind is the training and cruising ground just outside the park; Guriú''s river-and-mangrove approach","si":"expedition","blurb":"Preá''s flat, steady wind is the training and cruising ground just outside the park; Guriú''s river-and-mangrove approach","when":"Jul-Dec","commission":"IKO school package + kite-hotel stay"},{"name":"Tatajuba dunes + freshwater lagoon","si_tag":"expedition","tier":"essential","source":"https://www.getyourguide.com/jericoacoara-l105737/jericoacoara-tatajuba-beach-and-buggy-ride-t229207/","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"village half-swallowed by dunes, a magical freshwater lagoon with rafts, waterslide, SUP, and submerged hammocks, ~25 km by buggy via a ferry-crossing at Guriú","si":"expedition","blurb":"village half-swallowed by dunes, a magical freshwater lagoon with rafts, waterslide, SUP, and submerged hammocks, ~25 km by buggy via a ferry-crossing at Guriú","when":"Jul-Dec","commission":"full-day private buggy (~R$300-500/4pax)"},{"name":"Buggy the Rota das Emoções","si_tag":"expedition","tier":"comfort","source":"https://planetaexo.com/trips/pt/a/rota-das-emocoes-6-dias-lencois-jericoacoara","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the epic dune-buggy/4x4 arc Jeri → Delta do Parnaíba → Lençóis Maranhenses","si":"expedition","blurb":"the epic dune-buggy/4x4 arc Jeri → Delta do Parnaíba → Lençóis Maranhenses","when":"Jul-Dec","commission":"multi-day DMC land package (AOR)"},{"name":"Lençóis Maranhenses extension (via Barreirinhas/Atins)","si_tag":"romance","tier":"comfort","source":"https://ambiental.tur.br/destinos/jericoacoara-delta-e-lencois-maranhenses-com-atins/","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the surreal blue-lagoon-in-white-dunes national park ~500 km west via the Rota das Emoções, staged from Barreirinhas or the barefoot village of Atins","si":"romance","blurb":"the surreal blue-lagoon-in-white-dunes national park ~500 km west via the Rota das Emoções, staged from Barreirinhas or the barefoot village of Atins","when":"Jul-Dec","commission":"multi-day romance package via Rota das Emoções DMC (AOR)"},{"name":"Candlelit fresh-fish + terrace-pool sunset","si_tag":"romance","tier":"premier","source":"https://www.humboldttravel.co.uk/hotel/pousada-vila-kalango/","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Vila Kalango''s open-air candlelit fish dinner and sunset-magnet terrace pool","si":"romance","blurb":"Vila Kalango''s open-air candlelit fish dinner and sunset-magnet terrace pool","when":"Jul-Dec","commission":"luxe pousada F&B + honeymoon package"}],"faq":[{"q":"When is the best time to kitesurf in Jericoacoara?","a":"July–December is kite season because the dry-season trade wind blows nearly every day, running ~20–25 kt and building to 30–35 kt on September–November afternoons (strongest in November). This wind is the demand engine, so book schools and pousadas early — the curve switches on around late June / early July.","source":"wakeupstoked.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"What is there to do in Jericoacoara besides the beach?","a":"The signature rituals are free and natural: climb the Sunset Dune (Duna do Pôr do Sol) at dusk to watch the sun drop straight into the Atlantic — one of the few places in Brazil where it does — walk ~45 minutes to the Pedra Furada arch, and float in the wooden hammocks set in the shallows of crystal-clear Lagoa do Paraíso.","source":"nextstopbrazil.com, Accessed 2026-07-07","si_tag":"tropical"},{"q":"Is Jericoacoara good for a honeymoon?","a":"Yes, but set expectations at barefoot-luxe, not palace-luxury — exquisite bungalows, sand floors and candlelight. Vila Kalango (24 beachfront bungalows, MICHELIN Guide) anchors the lane, and the green Feb–May shoulder sells the quiet, glassy-lagoon honeymoon version when the pousadas discount.","source":"guide.michelin.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"What''s the real risk to plan for?","a":"Remoteness. Jeri is road-less, so definitive trauma care and complex medical evacuation route through Fortaleza — a 4x4-only, ~4–5 hr ground leg (or JJD air) — then international air evac as needed. Factor that into any emergency-response estimate; travel insurance with medical-evacuation cover is strongly advised.","source":"portaljericoacoara.com.br, Accessed 2026-07-07","si_tag":"safety"},{"q":"Is kitesurfing in Jericoacoara dangerous?","a":"Manageable with the right school: use IKO-certified schools (Rancho do Peixe/Ticowind, Preá Kite Club, North Kite Center, BLU). Central-Jeri offshore wind is not for beginners — they route to Preá''s flat water — and deep-water sessions warrant a life jacket, with a local briefing mandatory because of open-water current.","source":"ikointl.com, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Jericoacoara & the Ceará Coast, Brazil — Kitesurf Capital, Sunset Dune & Barefoot-Luxe Pousadas | TravelWell.World","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","search_language":"pt-BR","local_keywords":["Jericoacoara o que fazer","kitesurf Jeri","Lagoa do Paraíso","Duna do Pôr do Sol Jeri","Pedra Furada Jericoacoara","transfer Fortaleza Jericoacoara 4x4","Réveillon Jericoacoara","Rota das Emoções roteiro","pousada Jericoacoara frente mar"],"hreflang":["en","pt-BR"],"primary_keyword":"Jericoacoara & the Ceará Coast"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"live"},{"si":"romance","status":"live"}],"ultra":[{"name":"Vila Kalango","positioning":"24 beachfront bungalows, MICHELIN Guide, watersports center, candlelit fish","earning":"luxe-pousada commission + package cross-sell","mor":"package via DMC","tier":"premier"},{"name":"Essenza Hotel","positioning":"30-room 5-star, infinity pool, direct beach, sunset-dune views","earning":"affiliate + direct commission","mor":"room affiliate → package","tier":"premier","flag":"Relais & Chateaux affiliation NOT verified — do not claim"},{"name":"My Blue Hotel","positioning":"beachfront, spa, swim-up bar — premium boutique","earning":"affiliate + direct","mor":"room affiliate","tier":"$$"},{"name":"Casa Nomade","positioning":"boutique per prompt — UNVERIFIED this pass","earning":"hold until confirmed","mor":"-","tier":"flag"}],"source_verified":null,"hero":{"query":"Jericoacoara & the Ceará Coast, Brazil, Brazil"},"geo":{"lat":-2.7936,"lng":-40.514}}'::jsonb, 66),
