insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('lima-peru', '10S', 'Lima', 'Peru', 'The world''s table, on the Pacific', 'live', 'verified', 'kyoto', 'Lima, South Coast & Amazon', '{"romance","expedition","culinary","culture"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Home to the World''s #1 restaurant 2025 (Maido, Nikkei) plus Central (former #1, Best of the Best), Kjolle #9, Merito #26, Mayta #39 - a global top-tier food capital.","Pre-Inca adobe pyramids inside the modern city (Huaca Pucllana, ~200-700 AD, in Miraflores) alongside the UNESCO colonial Centro Historico and the Convento de San Francisco catacombs.","Jorge Chavez (LIM) is South America''s newest mega-hub: new $2.4B Fraport/LAP terminal opened June 1, 2025 (3x size, up to 40M pax/yr, 46 gates, 2nd runway); the gateway to Cusco/MP, the Amazon, Titicaca and the south coast.","Cool Pacific-desert climate: warm sunny summer Dec-Apr; grey misty ''garua'' winter May-Nov (dry but overcast) - the driest window for Machu Picchu, which drives Lima''s derivative winter spike.","Bohemian Barranco (Puente de los Suspiros) and clifftop Miraflores (Malecon, Costa Verde paragliding) anchor the boutique-romance line; genuine global-flag ultra (Belmond, Relais & Chateaux, LHW, JW Marriott)."],"safety":{"emergency":"105 National Police (PNP) / 106 SAMU medical-ambulance / 116 Bomberos (fire); iPeru tourist assistance (01-574-8000, desks at LIM/Miraflores/Larcomar)","hospital":"Lima has Peru''s best private hospitals/clinics (Clinica Anglo Americana, Ricardo Palma, Clinica Internacional) for stabilization; serious trauma routes to US medical evacuation - carry evac-capable insurance","advisory_level":"L2","bin":"freely bookable (L2)","book_enabled":true,"consent_flow":"none (L2 is standard-caution, below disclosure threshold)","l3_disclosure":false,"air_access_verified":true,"air_access_note":"Jorge Chavez Intl (LIM), Callao - new Fraport/LAP terminal opened 2025-06-01; SA hub; LIM->Miraflores ~45-60 min via hotel/DMC transfer (not street taxi)","urban_crime_discipline":"stay in Miraflores/Barranco/San Isidro; registered radio-taxi or ride-hail app or hotel transfer only (never unmarked street taxi - express-kidnapping setup); beware distraction theft; in-bank ATMs only; don''t display valuables","state_of_emergency_note":"Lima/Callao late-2025 state of emergency raised police/military presence amid rising urban crime - does not change L2 bin; verify current status live","altitude":"Lima at sea level (no altitude issue; useful soft-landing before Cusco 3,400 m / Titicaca 3,800 m)","dengue":"low on cool Lima coast; higher on Amazon/northern extensions","malaria":"no malaria risk in Lima (highland/coastal capital); Amazon extensions do carry risk - CDC consult for those legs","water":"bottled/purified only (also underpins reputable-cebicheria raw-fish hygiene rule)","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel Within 20km south of the Peru-Colombia border FCDO advises against all but essential travel to areas within 20km south of the Putumayo River and the border between Peru and Colombia (Loreto region) except for: the Amazon River the area of the triple border with Brazil and Colombia from and including the towns of Caballococha in Peru up to the actual triple border at Santa Rosa de Yavari town Valley of the Apurímac, Ene, and Mantaro Rivers ( VRAEM ) FCDO advises against all but essential travel to the Valley of the Apurímac, Ene, and Mantaro Rivers, also known as the VRAEM region."},{"form":"against all but essential travel","text":"advise against all but essential travel to these two areas for safety and security reasons."},{"form":"against all but essential travel","text":"advises against all but essential travel to areas within 20km south of the Putumayo River and the border between Peru and Colombia (Loreto region) except for: the Amazon River the area of the triple border with Brazil and Colombia from and including the towns of Caballococha in Peru up to the actual triple border at Santa Rosa de Yavari town This is due to a high level of violence from organised criminal gangs who produce and traffic illegal drugs."},{"form":"against all but essential travel","text":"advises against all but essential travel to the Valley of the Apurímac, Ene and Mantaro Rivers, also known as the VRAEM region."},{"form":"against all but essential travel","text":"advises against all but essential travel."}],"url":"https://www.gov.uk/foreign-travel-advice/peru","read":"2026-08-19","page_updated":"2026-06-22T23:35:12+01:00"}},"timing":{"peak_coastal_summer":"Dec-Apr - Lima''s own warm/sunny curve (beaches, nightlife, paragliding, surfing); highest crowds/prices","inflection_gateway_winter":"Jun-Aug - derivative spike as travelers bookend the driest Machu Picchu window through Lima","garua":"May-Nov grey misty sea-fog winter (dry but overcast); sell as culinary/culture bookend, not beach","fire_date":"coastal-summer curve: fire ~mid-November (curve-start -1-2 wks); MP-derivative winter curve: fire ~mid-May; practically, attach Lima nights to whenever the parent Cusco/MP campaign fires","booking_lead":"top tasting menus (Central/Maido/Kjolle) weeks ahead - reservation-first; city hotels 2-3 months for summer; Cusco/Amazon-attached bookends 3-6 months","shoulder":"Apr-May & Sep-Nov (better deals, workable weather)","off_season_specials":"grey-winter ''gastronomy bookend'': tasting-menu circuit, cebicheria lunches, Larco/Pachacamac/San Francisco heritage, cooking classes, pisco-sour masterclasses","event_peaks":["Fiestas Patrias late July (Independence, domestic peak)","Mistura-successor gastronomy festival (name/dates UNVERIFIED - confirm live)","Christmas/New Year (summer)"]},"jewels":[{"name":"Central / Maido / Kjolle tasting menus","si_tag":"Culinary","status":"future","hook":"The world-ranked Lima fine-dining trinity - Maido (World''s #1 2025), Central (Best of the Best), Kjolle (#9); book weeks ahead, reservation-first.","bookable_category":"direct reservation or DMC culinary program","tier":"ultra","source":"https://www.theworlds50best.com/stories/News/maido-lima-the-worlds-best-restaurant-2025.html","si":"culinary","blurb":"The world-ranked Lima fine-dining trinity - Maido (World''s #1 2025), Central (Best of the Best), Kjolle (#9); book weeks ahead, reservation-first.","commission":"DMC culinary-program AOR 10-15%; raw restaurant deposit pass-through"},{"name":"La Mar cebicheria (Gaston Acurio)","si_tag":"Culinary","status":"future","hook":"Acurio''s flagship Miraflores cebicheria (est. 2005), Latin America''s 50 Best - the definitive lunch-only ceviche experience.","bookable_category":"direct / DMC food tour (lunch only)","tier":"premier","source":"http://limacitykings.com/la-mar-cebicheria-peruana/","si":"culinary","blurb":"Acurio''s flagship Miraflores cebicheria (est. 2005), Latin America''s 50 Best - the definitive lunch-only ceviche experience.","commission":"DMC food-program AOR / Viator affiliate 4-8%; walk-in pass-through"},{"name":"Pisco Sour at the Country Club English Bar","si_tag":"Culinary","status":"future","hook":"SUMMUM-award-winning Pisco Sour (2012/2013/2022 best bar in Lima) in the 1927 hotel''s traditional English Bar.","bookable_category":"walk-in / hotel guest","tier":"premier","source":"https://en.wikipedia.org/wiki/Country_Club_Lima_Hotel","si":"culinary","blurb":"SUMMUM-award-winning Pisco Sour (2012/2013/2022 best bar in Lima) in the 1927 hotel''s traditional English Bar.","commission":"pairs with Country Club stay (hotel AOR); bar spend pass-through"},{"name":"Huaca Pucllana","si_tag":"Culture & Heritage","status":"future","hook":"Pre-Inca (~200-700 AD) adobe pyramid in the heart of Miraflores, with an acclaimed on-site restaurant overlooking the floodlit ruin.","bookable_category":"site tour / restaurant","tier":"premier","source":"https://www.tripadvisor.com/Attraction_Review-g294316-d311722-Reviews-Huaca_Pucllana-Lima_Lima_Region.html","si":"culture","blurb":"Pre-Inca (~200-700 AD) adobe pyramid in the heart of Miraflores, with an acclaimed on-site restaurant overlooking the floodlit ruin.","commission":"DMC/affiliate on tour; site fee + restaurant pass-through"},{"name":"Convento de San Francisco catacombs","si_tag":"Culture & Heritage","status":"future","hook":"1540 Franciscan monastery in the UNESCO Centro Historico with catacombs holding tens of thousands of bones.","bookable_category":"guided city tour","tier":"comfort","source":"https://kaypiperutours.com/must-visit-attractions-in-lima/","si":"culture","blurb":"1540 Franciscan monastery in the UNESCO Centro Historico with catacombs holding tens of thousands of bones.","commission":"DMC/affiliate 4-10%; entry pass-through"},{"name":"Larco Museum (Museo Larco)","si_tag":"Culture & Heritage","status":"future","hook":"Pre-Columbian masterpiece collection in an 18th-c. mansion over a pyramid, with a famed garden restaurant; the ''Huacas & Larco by night'' tour is a classic.","bookable_category":"entry / night tour + dinner","tier":"premier","source":"https://www.viator.com/tours/Lima/Huacas-and-Larco-Museum-by-Night-with-Dinner/d928-7465P4","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Pre-Columbian masterpiece collection in an 18th-c. mansion over a pyramid, with a famed garden restaurant; the ''Huacas & Larco by night'' tour is a classic.","when":"year-round","commission":"Viator night-tour affiliate 4-8%; entry pass-through"},{"name":"Pachacamac archaeological complex","si_tag":"Culture & Heritage","status":"future","hook":"Vast pre-Inca/Inca pilgrimage city (pyramids, temples, plazas) ~30 km south of Lima with an on-site museum; easy half-day.","bookable_category":"DMC/Viator day tour","tier":"comfort","source":"https://kaypiperutours.com/must-visit-attractions-in-lima/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Vast pre-Inca/Inca pilgrimage city (pyramids, temples, plazas) ~30 km south of Lima with an on-site museum; easy half-day.","when":"year-round","commission":"DMC 10-12% / affiliate 4-8%; site entry pass-through"},{"name":"Callao Monumental street-art district","si_tag":"Culture & Heritage","status":"future","hook":"Regenerated Callao port-district arts quarter - murals, galleries and design studios in old republican buildings; go with a vetted tour.","bookable_category":"guided art tour (zone awareness)","tier":"comfort","source":"https://kaypiperutours.com/must-visit-attractions-in-lima/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Regenerated Callao port-district arts quarter - murals, galleries and design studios in old republican buildings; go with a vetted tour.","when":"year-round","commission":"DMC/affiliate 4-10%; confirm live tour product + safe corridor"},{"name":"Barranco + Puente de los Suspiros","si_tag":"Romance & Honeymoons","status":"live","hook":"Bohemian seafront district - murals, galleries, the romance-legend Bridge of Sighs and sunset bars; Lima''s honeymoon base.","bookable_category":"self-guided within corridor / guided art walk","tier":"luxury","source":"https://kaypiperutours.com/must-visit-attractions-in-lima/","si":"romance","blurb":"Bohemian seafront district - murals, galleries, the romance-legend Bridge of Sighs and sunset bars; Lima''s honeymoon base.","commission":"pairs with Hotel B/Barranco boutique stay (hotel AOR); walk affiliate 4-8%"},{"name":"Miraflores Malecon + Parque del Amor at sunset","si_tag":"Romance & Honeymoons","status":"live","hook":"Clifftop coastal promenade above the Pacific with the mosaic ''Park of Love'' - the classic Lima romance postcard, free.","bookable_category":"free / paired with clifftop dinner","tier":"essential","source":"https://kaypiperutours.com/must-visit-attractions-in-lima/","si":"romance","blurb":"Clifftop coastal promenade above the Pacific with the mosaic ''Park of Love'' - the classic Lima romance postcard, free.","commission":"bundled into commissionable romance program / dinner"},{"name":"Tandem paragliding off the Miraflores cliffs","si_tag":"Global Expedition Adventures","status":"live","hook":"Guided tandem flight over the Costa Verde clifftops and Pacific from the ~80 m Miraflores launch - the signature Lima adventure.","bookable_category":"reputable tandem operator / Viator (guided-only)","tier":"premier","source":"https://pariwana-hostel.com/en/blog/2025/10/07/paragliding-in-lima-a-complete-guide-to-flying-over-the-costa-verde/","si":"expedition","blurb":"Guided tandem flight over the Costa Verde clifftops and Pacific from the ~80 m Miraflores launch - the signature Lima adventure.","commission":"affiliate 4-8% / DMC 10-12%"},{"name":"Costa Verde surf lesson","si_tag":"Global Expedition Adventures","status":"live","hook":"Guided surf school on the Miraflores/Barranco beach breaks (Makaha/Waikiki); cold-water summer swell, certified instructor + wetsuit.","bookable_category":"surf school / Viator (guided-only)","tier":"comfort","source":"https://pariwana-hostel.com/en/blog/2025/10/07/paragliding-in-lima-a-complete-guide-to-flying-over-the-costa-verde/","si":"expedition","blurb":"Guided surf school on the Miraflores/Barranco beach breaks (Makaha/Waikiki); cold-water summer swell, certified instructor + wetsuit.","commission":"affiliate 4-8%"}],"faq":[{"q":"How do I actually get a table at Maido, Central or Kjolle?","a":"Book weeks ahead — the tables are the binding constraint, not the hotel. Central, Maido and Kjolle open reservations on a rolling monthly/multi-week basis and sell out, so the culinary itinerary must be built reservation-first; grey winter is fine because the dining is indoors.","source":"ohlalima.com, 2026-07-07","si_tag":"culinary"},{"q":"What can I see in Lima in a day or two?","a":"More than you''d expect for a gateway city. Walk to Huaca Pucllana (a ~200–700 AD adobe pyramid in Miraflores), the Convento de San Francisco (founded 1540) catacombs in the UNESCO Centro Histórico, and the Larco Museum''s 5,000-year pre-Columbian collection in an 18th-century mansion.","source":"kaypiperutours.com, 2026-07-07","si_tag":"culture"},{"q":"Is Lima good for a honeymoon?","a":"Yes — the base is bohemian Barranco, Lima''s most walkable, romantic district, home to the Puente de los Suspiros (\"Bridge of Sighs\") and to Hotel B, a restored 1914 Belle Époque arts-mansion that is the city''s only Relais & Châteaux.","source":"relaischateaux.com, 2026-07-07","si_tag":"romance"},{"q":"What''s the real risk to plan for in Lima?","a":"Urban street crime, not any activity. Stay in Miraflores, Barranco and San Isidro; use only registered radio-taxis, ride-hail apps or hotel transfers — never an unmarked street taxi, the classic express-kidnapping setup (forced ATM withdrawals over 1–3 hours). Use in-bank ATMs and keep valuables out of sight.","source":"bushop.com, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Lima Peru Travel Guide 2026 — World''s #1 Restaurant, Pre-Inca Ruins & Barranco | TravelWell.World","meta_description":"Plan Lima, Peru: the world''s #1 restaurant (Maido), Central, Kjolle and La Mar; pre-Inca Huaca Pucllana, Larco Museum and Pachacamac; bohemian Barranco; luxury Belmond & Relais & Chateaux stays; and clear L2 safety with zone/taxi coaching.","slug":"lima-peru","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-07","search_language":["en","es-PE"],"local_keywords":["qué hacer en Lima","mejores restaurantes Lima","Barranco Miraflores","Puente de los Suspiros","tour Huaca Pucllana","Museo Larco","Pachacámac desde Lima","parapente Costa Verde Lima","mejor época para viajar a Lima","cebicherías Lima","pisco sour Lima"],"hreflang":["en","es-PE"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"romance","status":"live"},{"si":"expedition","status":"live"},{"si":"culinary","status":"future"},{"si":"culture","status":"future"}],"ultra":[{"name":"Miraflores Park, A Belmond Hotel","why_ultra":"82-room clifftop Pacific-Riviera flagship in Miraflores; boutique service + full-luxury amenities; Lima''s iconic ultra address and a Belmond = Virtuoso-preferred flag (CLAUDE.md moat)","earning":"on application / host-Virtuoso or Fora (Amex FHR-listed)","virtuoso_value_add":"Virtuoso-preferred / consortia amenities where eligible (verify)","mor":true,"tier":"ultra"},{"name":"Hotel B","why_ultra":"Lima''s only Relais & Chateaux - restored 1914 Belle Epoque arts-mansion in Barranco, connected to the Lucia de la Puente gallery; the romance/honeymoon ultra pick","earning":"on application / Fora or Relais & Chateaux consortia where eligible","virtuoso_value_add":"consortia amenities where eligible (verify)","mor":true,"tier":"ultra"},{"name":"Country Club Lima Hotel","why_ultra":"five-star 1927 San Isidro landmark (California-colonial, national heritage), Leading Hotels of the World; award-winning Perroquet + SUMMUM-winning English Bar Pisco Sour; living-history grandeur","earning":"on application / host-Virtuoso or Fora / LHW Leaders Club where eligible","virtuoso_value_add":"LHW/consortia amenities where eligible (verify)","mor":true,"tier":"luxury"},{"name":"JW Marriott Hotel Lima","why_ultra":"oceanfront Miraflores tower on the Costa Verde clifftop, steps from Larcomar/Malecon; best-located branded-luxury oceanfront with Bonvoy + STARS/Luminous eligibility","earning":"on application / Marriott STARS/Luminous or Fora where eligible","virtuoso_value_add":"STARS/Luminous amenities where eligible (verify)","mor":true,"tier":"luxury"}],"source_verified":"2026-07-07","hero":{"query":"Lima, Peru"},"geo":{"lat":-12.0464,"lng":-77.0428}}'::jsonb, 70),
  ('los-barriles-mexico', '10S', 'Los Barriles', 'Mexico', 'Los Barriles kiteboarding', 'live', 'verified', 'tropicalBeach', 'Baja California Sur (Los Cabos & La Paz)', '{"ocean","expedition","tropical"}', '{"tropical"}', '{"comfort","premier"}', null, null, '{"key_facts":["East Cape town on the Sea of Cortez, ~1 hr from Los Cabos Airport / ~40 min from La Paz","El Norte kite/wind season Nov 1 - end of March; N/NE crosswind 15-30 knots, afternoon peak","Offshore sportfishing peaks May-early November (marlin, sailfish, dorado, wahoo, tuna); glass-calm","Dorado Shoot Out (~mid-July, ~140 boats) is the largest dorado tournament in Baja; East Cape Offshore / Bisbee''s circuit opener nearby","Villas + fishing lodges are the lodging rung (Van Wormer Palmas de Cortez / Playa del Sol); northern gateway to Cabo Pulmo"],"safety":{"emergency":"911","hospital":"remote small town, no major trauma on-site; La Paz ~40 min (Hospital Salvatierra/private) or Los Cabos/San Jose del Cabo ~1 hr (private) - FLAG MEDEVAC DISTANCE; carry medical + evac insurance","advisory_level":"L2","malaria":"effectively none in Baja California Sur","dengue":"circulates in Mexico - use repellent","water":"drink bottled/purified water","hurricane":"Jun-Nov - trip insurance for summer/fall","wind_watersport":"El Norte 15-30 kt with offshore-drift risk - lessons with rescue-boat cover, correct kite size, helmet/impact vest for beginners","offshore_fishing":"open Sea of Cortez - licensed charter, VHF, life jackets, float plan, sun/heat protection; slow rescue on remote coast","dive":"diving south at Cabo Pulmo (separate dossier); nearest hyperbaric chamber Los Cabos or La Paz; no-fly 18-24h; DAN +1-919-684-9111; remote-distance flag","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Nov-Mar (El Norte kite/wind season) - highest occupancy, schools full, villas booked; whale + whale-shark window","shoulder":"Apr & Oct (wind tapering / fishing ramping; softer rates)","green":"May-early Nov (glass-calm offshore = billfish/dorado peak + summer tournaments; desert heat + hurricane window Jun-Nov)","booking_window_lead_time":"villas + fishing lodges for Nov-Mar wind season and summer tournament dates book 4-9 months ahead; tournament weeks (Dorado Shoot Out mid-July, East Cape Offshore) tightest; shoulder short-lead; verify current tournament dates","out_of_season_fill_the_beds":"Apr-May/Oct = calm-water Sea of Cortez beach town + snorkel/SUP + ATV + Cabo Pulmo day trips; La Paz whale-shark add-ons Oct-Apr; summer = glass-calm offshore fishing + tournament energy","holiday_event_peaks":"Christmas-New Year (peak wind + snowbird villas), Semana Santa, Mexican summer holidays; tournament weekends spike lodging hardest","campaign_start_trigger":"open kite/wind campaigns late summer (for Nov-Mar); open sportfishing/tournament campaigns late winter (for May-Nov); market kite and fishing audiences separately - opposite seasons","event_peaks":["El Norte kite/wind Nov-Mar","Dorado Shoot Out ~mid-July + East Cape Offshore / Bisbee''s opener","whale season Dec-Apr","La Paz whale sharks ~Oct-Apr"],"sources":["https://www.wahoowind.com/about","https://vanwormerresorts.com/sport-fishing","https://discoverbaja.com/2026/06/03/summer-2026-baja-fishing-tournaments/","https://sallysees.com/whale-watching-in-baja-california-sur/"]},"jewels":[{"name":"El Norte kiteboarding season (Nov-Mar)","si_tag":"Ocean Adventures","status":"future","tier":"premier","bookable":"Wahoo Wind Co. / Vela Baja lessons + rentals","source":"https://www.wahoowind.com/about","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"reliable 15–30 kt N/NE cross-wind on a protected sandy bay","si":"ocean","blurb":"reliable 15–30 kt N/NE cross-wind on a protected sandy bay","when":"Nov-Mar","commission":"kite-school operator on application + GYG affiliate"},{"name":"Wingfoil / windsurf clinics","si_tag":"Ocean Adventures","status":"future","tier":"premier","bookable":"local wind schools","source":"https://middlecasa.com/why-los-barriles-is-mexicos-winter-mecca-for-kitesurfers/","hook":"multi-day progression on the same El Norte wind","si":"ocean","blurb":"multi-day progression on the same El Norte wind","commission":"operator on application"},{"name":"Offshore billfish/dorado charter","si_tag":"Ocean Adventures","status":"future","tier":"premier","bookable":"Van Wormer fleet / Charter Maria Teresa","source":"https://vanwormerresorts.com/sport-fishing","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","when":"Nov-Mar","commission":"charter on application"},{"name":"Dorado Shoot Out tournament week","si_tag":"Ocean Adventures","status":"future","tier":"premier","bookable":"tournament entry + Palmas de Cortez lodging","source":"https://discoverbaja.com/2026/06/03/summer-2026-baja-fishing-tournaments/","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"~mid-July, ~140 boats, largest dorado tournament in Baja","si":"ocean","blurb":"~mid-July, ~140 boats, largest dorado tournament in Baja","when":"Nov-Mar","commission":"lodge/charter on application"},{"name":"ATV / off-road desert + beach run","si_tag":"GEA","status":"live","tier":"comfort","bookable":"Los Barriles Adventures / local ATV operators","source":"https://www.tripadvisor.com/Attraction_Review-g1544261-d23230066-Reviews-Los_Barriles_Adventures-Los_Barriles_Baja_California.html","hook":"quad rides into the sierra to remote beaches, snorkel coves, historic lighthouse","si":"expedition","blurb":"quad rides into the sierra to remote beaches, snorkel coves, historic lighthouse","commission":"operator + Viator affiliate"},{"name":"Winter whale watching (offshore)","si_tag":"GEA","status":"live","tier":"comfort","bookable":"local boat operators / Amstar","source":"https://sallysees.com/whale-watching-in-baja-california-sur/","si":"expedition","commission":"operator + affiliate"},{"name":"La Paz whale-shark day trip","si_tag":"GEA","status":"live","tier":"premier","bookable":"La Paz operator day trip + transfer","source":"https://www.cabopulmopark.com/","si":"expedition","commission":"operator + Viator affiliate"},{"name":"Calm-water Sea of Cortez beach day (off-wind season)","si_tag":"Tropical Islands","status":"future","tier":"comfort","bookable":"villa + local SUP/snorkel rental","source":"https://www.globeguide.ca/travel-guide-los-barriles-mexico/","hook":"swim/snorkel/SUP the warm gulf when El Norte is down","si":"tropical","blurb":"swim/snorkel/SUP the warm gulf when El Norte is down","commission":"rental + villa"}],"faq":[{"q":"When is kiteboarding season in Los Barriles?","a":"November 1 to the end of March, when the \"El Norte\" wind blows a reliable 15–30 kt N/NE crosswind, building mid-morning and peaking in the afternoon. The wide, protected sandy bay suits all levels — book instructors and beachfront villas 4–9 months out.","source":"wahoowind.com, 2026-07-04","si_tag":"ocean"},{"q":"When is the fishing best, and what''s the big tournament?","a":"Offshore peaks May to early November in glass-calm water for marlin, dorado, wahoo and tuna, and the marquee event is the mid-July Dorado Shoot Out — ~140 boats, Baja''s largest dorado tournament. Kite and fishing are opposite seasons, so plan for one or the other.","source":"vanwormerresorts.com / discoverbaja.com, 2026-07-04","si_tag":"ocean"},{"q":"What else is there beyond wind and fish?","a":"Winter whale-watching (Dec–Apr) offshore, ATV desert-and-beach runs year-round, and the La Paz whale-shark snorkel ~40 minutes north (Oct–Apr). Off the wind season (Apr–Oct) the Sea of Cortez turns calm for swimming, snorkel and SUP.","source":"sallysees.com / globeguide.ca, 2026-07-04","si_tag":"expedition"},{"q":"Is kiteboarding here dangerous?","a":"It''s for the prepared — the core hazard is offshore drift. El Norte''s 15–30 kt N/NE wind is side-offshore, so a downed kiter drifts toward open sea; take lessons with a school running rescue-boat cover, use the right kite size and self-rescue skills, and check the daily wind before launch.","source":"wahoowind.com, 2026-07-04","si_tag":"safety"}],"seo":{"meta_title":"Los Barriles Mexico: Kiteboarding, Fishing & El Norte Winds 2026","meta_description":"Los Barriles on Baja''s East Cape — El Norte kiteboarding season (Nov–Mar), world-class marlin/dorado sportfishing, villas, ATV desert runs and the gateway to Cabo Pulmo.","slug":"los-barriles-mexico","primary_keyword":"Los Barriles kiteboarding","long_tail":["Los Barriles El Norte wind season","Los Barriles sportfishing dorado marlin","Dorado Shoot Out tournament Los Barriles","Los Barriles East Cape villa rentals","kitesurfing Los Barriles vs La Ventana"],"search_language":["en","es-MX"],"local_keywords":["Los Barriles kitesurf temporada El Norte","pesca deportiva Los Barriles dorado marlin","torneo Dorado Shoot Out Los Barriles","villas renta Los Barriles Baja","clases de kite Los Barriles","qué hacer en Los Barriles","Los Barriles cómo llegar desde Los Cabos"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"ocean","status":"future"},{"si":"GEA (Great Escapes & Adventures)","status":"live"},{"si":"tropical","status":"future"}],"ultra":[{"name":"Hotel Palmas de Cortez (Van Wormer)","posture":"premier fishing resort + tournament host in-town; not five-star brand","price_tier":"premier","earning":"on application via host / DMC","virtuoso_value_add":"n/a-branded - treat as premier fishing lodge","mor":"no net-rate resale","source":"https://vanwormerresorts.com/"},{"name":"Premier beachfront villas (Punta Pescadero / Los Barriles)","posture":"top private-stay rung locally for wind-week/fishing groups","price_tier":"luxury","earning":"on application via host / villa manager","virtuoso_value_add":"private villa + kite/fishing days brought in","mor":"agency terms, no net-rate resale","source":"https://abajavacation.com/"}],"source_verified":"2026-07-04","hero":{"query":"Los Barriles, Mexico"},"geo":{"lat":23.682,"lng":-109.696}}'::jsonb, 71),
